import{_ as a,o as s,c as t,ag as n}from"./chunks/framework.Quf--mN6.js";const u=JSON.parse('{"title":"Autoloading","description":"","frontmatter":{},"headers":[],"relativePath":"rails/autoloading.md","filePath":"rails/autoloading.md","lastUpdated":1777563775000}'),d={name:"rails/autoloading.md"};function o(r,e,i,l,c,p){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="autoloading" tabindex="-1">Autoloading <a class="header-anchor" href="#autoloading" aria-label="Permalink to &quot;Autoloading&quot;">​</a></h1><p>Servus relies on Rails autoloading for services and uses its Railtie to eager-load guards and event handlers. No manual <code>require</code> statements needed.</p><h2 id="services" tabindex="-1">Services <a class="header-anchor" href="#services" aria-label="Permalink to &quot;Services&quot;">​</a></h2><p>Services follow standard Rails autoloading — the file path maps to the constant:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>app/services/treasury/transfer_gold/service.rb  →  Treasury::TransferGold::Service</span></span>
<span class="line"><span>app/services/ravens/dispatch_message/service.rb  →  Ravens::DispatchMessage::Service</span></span></code></pre></div><p>Support classes inside the namespace also autoload:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>app/services/treasury/transfer_gold/support/balance_snapshot.rb  →  Treasury::TransferGold::Support::BalanceSnapshot</span></span></code></pre></div><h2 id="guards" tabindex="-1">Guards <a class="header-anchor" href="#guards" aria-label="Permalink to &quot;Guards&quot;">​</a></h2><p>The Railtie eager-loads all <code>*_guard.rb</code> files from the configured <code>guards_dir</code> (default: <code>app/guards</code>) on every request in development and once at boot in production:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>app/guards/eligible_transfer_guard.rb  →  EligibleTransferGuard</span></span>
<span class="line"><span>app/guards/sufficient_balance_guard.rb →  SufficientBalanceGuard</span></span></code></pre></div><p>Guards must follow the <code>*_guard.rb</code> naming convention to be discovered.</p><h2 id="event-handlers" tabindex="-1">Event handlers <a class="header-anchor" href="#event-handlers" aria-label="Permalink to &quot;Event handlers&quot;">​</a></h2><p>The Railtie eager-loads all <code>*_handler.rb</code> files from the configured <code>events_dir</code> (default: <code>app/events</code>). In development, the event bus is cleared before reloading to prevent duplicate subscriptions:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>app/events/gold_transferred_handler.rb  →  GoldTransferredHandler</span></span>
<span class="line"><span>app/events/message_dispatched_handler.rb →  MessageDispatchedHandler</span></span></code></pre></div><h2 id="railtie-extensions" tabindex="-1">Railtie extensions <a class="header-anchor" href="#railtie-extensions" aria-label="Permalink to &quot;Railtie extensions&quot;">​</a></h2><p>The Railtie also wires up additional features when their dependencies are available:</p><table tabindex="0"><thead><tr><th>Extension</th><th>Loads when</th><th>What it adds</th></tr></thead><tbody><tr><td>Controller helpers</td><td><code>ActionController</code> loads</td><td><code>run_service</code> and <code>render_service_error</code> on all controllers</td></tr><tr><td>Async execution</td><td><code>ActiveJob</code> loads</td><td><code>.call_async</code> on all services</td></tr><tr><td>Lazy resolvers</td><td><code>ActiveRecord</code> loads</td><td><code>lazily</code> DSL on all services</td></tr></tbody></table><p>These are loaded via <code>ActiveSupport.on_load</code>, so they only activate when the corresponding Rails component is present.</p>`,18)])])}const g=a(d,[["render",o]]);export{u as __pageData,g as default};
